INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'doi'), 'A1', 'greetings', 'Greetings', 'Greet people in Dogri and introduce yourself.', 'You''ve just rented a room in Gandhi Nagar, Jammu. Sharma ji, the landlord, comes to say hello.', '“Namaste” and “Ram Ram” are everyday greetings in Jammu, and “Jai Mata Di” is heard everywhere, for the Vaishno Devi pilgrimage. Dogri says “tus” (you, polite) and adds “ji” to be respectful.', 1, 'published', datetime('now'), datetime('now'), 1);
